function Hash([string]$p) { $f=Get-Item -LiteralPath $p -Force;if($f.PSIsContainer -or ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $f.Length -gt 67108864){throw 'bounded regular file required'};(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant() }
function Save-File([string]$src,[string]$dst) { $parent=Split-Path -Parent $dst;New-Item -ItemType Directory -Path $parent -Force|Out-Null;Copy-Item -LiteralPath $src -Destination $dst -Force }
function Safe-Rel([string]$rel) { if([string]::IsNullOrWhiteSpace($rel) -or $rel -match '(^/|\\|:|(^|/)\.\.(\/|$))'){throw 'unsafe relative source row'} }
$oldPlan=Get-Content -LiteralPath $plan -Raw|ConvertFrom-Json
