$oldRows=@($oldPlan.sourceBindings)
foreach($r in $oldRows){Safe-Rel ([string]$r.path);$src=Join-Path $pkg $r.path;if(-not (Test-Path -LiteralPath $src)){throw ('prior source missing: '+$r.path)};Save-File $src (Join-Path $saved ('prior-package\'+$r.path))}
$archive=[ordered]@{kind='factory-custom-layout-source-archive-v1';priorPlanSha256=(Hash (Join-Path $saved 'plan-prebuild-v4-r1.json'));priorBuilderSha256=(Hash (Join-Path $saved 'build-owned-pilot-v1-r1.ps1'));priorHelperSha256=(Hash (Join-Path $saved 'Sr0OwnedJobProcess-r1.cs'));priorSourceCount=$oldRows.Count;archivedAt=[DateTimeOffset]::UtcNow.ToString('o')}
